{
    "vllm/lora/ops/triton_ops/fused_moe_lora_op.py": {
        "_fused_moe_lora_kernel": "@triton.jit\ndef _fused_moe_lora_kernel(\n    a_ptr,\n    b_ptr,\n    c_ptr,\n    topk_weights_ptr,\n    sorted_token_ids_ptr,\n    expert_ids_ptr,\n    num_tokens_post_padded_ptr,\n    # Matrix dimensions\n    N,\n    K,\n    EM,\n    num_valid_tokens,\n    num_experts,\n    # The stride variables represent how much to increase the ptr by when\n    # moving by 1 element in a particular dimension. E.g. `stride_am` is\n    # how much to increase `a_ptr` by to get the element one row down\n    # (A has M rows).\n    stride_am,\n    stride_ak,\n    stride_bl,\n    stride_be,\n    stride_bk,\n    stride_bn,\n    stride_cm,\n    stride_cn,\n    stride_tl,\n    stride_el,\n    # Meta-parameters\n    num_slice_a: tl.constexpr,\n    num_slice_c: tl.constexpr,\n    slice_a_size: tl.constexpr,\n    slice_c_size: tl.constexpr,\n    top_k: tl.constexpr,\n    MUL_ROUTED_WEIGHT: tl.constexpr,\n    BLOCK_SIZE_M: tl.constexpr,\n    BLOCK_SIZE_N: tl.constexpr,\n    BLOCK_SIZE_K: tl.constexpr,\n    GROUP_SIZE_M: tl.constexpr,\n):\n    \"\"\"\n    Triton kernel for fused MoE + LoRA forward pass.\n    \n    For each token, selects a LoRA module based on token-level LoRA mapping,\n    applies multiple expert-specific low-rank adapters (LoRA A and LoRA B) \n    to the token's hidden state according to top-k expert indices.\n    \n    Computation per token i and expert x:\n        output[i, x, :] = hidden_states[i] @ lora_a[lora_idx, expert_id].T @ lora_b[lora_idx, expert_id].T\n    \n    This is equivalent to:\n        output[i, x, :] = sum_em(sum_k(hidden[k] * lora_a[em, k]) * lora_b[n, em])\n    \n    We compute this by iterating over EM and accumulating:\n        For each em: intermediate[em] = sum_k(hidden[k] * lora_a[em, k])\n                     output[n] += intermediate[em] * lora_b[n, em]\n    \"\"\"\n    # Program ID determines which token and output block we're processing\n    pid = tl.program_id(axis=0)\n    \n    # Calculate token index and output block index\n    num_output_blocks = tl.cdiv(N, BLOCK_SIZE_N)\n    token_idx = pid // num_output_blocks\n    output_block_idx = pid % num_output_blocks\n    \n    # Check if this token is within valid range\n    if token_idx >= num_valid_tokens:\n        return\n    \n    # Calculate output column range for this block\n    output_col_start = output_block_idx * BLOCK_SIZE_N\n    output_col_range = output_col_start + tl.arange(0, BLOCK_SIZE_N)\n    output_col_mask = output_col_range < N\n    \n    # Get the original token index from sorted_token_ids\n    orig_token_idx = tl.load(sorted_token_ids_ptr + token_idx)\n    \n    # Load hidden state for this token: shape (K,)\n    hidden_offset = orig_token_idx * stride_am\n    hidden_range = tl.arange(0, BLOCK_SIZE_K)\n    hidden_mask = hidden_range < K\n    hidden = tl.load(\n        a_ptr + hidden_offset + hidden_range * stride_ak,\n        mask=hidden_mask,\n        other=0.0\n    ).to(tl.float32)\n    \n    # Process each of the top-k experts for this token\n    for k_idx in range(top_k):\n        # Load expert ID for this token and expert position\n        expert_id = tl.load(\n            expert_ids_ptr + token_idx * stride_el + k_idx * stride_tl\n        ).to(tl.int32)\n        \n        # Load routing weight if needed\n        if MUL_ROUTED_WEIGHT:\n            weight = tl.load(\n                topk_weights_ptr + orig_token_idx * top_k + k_idx\n            ).to(tl.float32)\n        else:\n            weight = 1.0\n        \n        # Load LoRA A weights for this expert: shape (EM, K)\n        # lora_a[lora_idx, expert_id] has shape (max_lora_rank, K)\n        lora_a_base = b_ptr + orig_token_idx * stride_bl + expert_id * stride_be\n        \n        # Load LoRA B weights for this expert: shape (N, EM)\n        # lora_b[lora_idx, expert_id] has shape (N, max_lora_rank)\n        # B weights are stored at an offset from A weights\n        lora_b_offset_elements = num_experts * EM * K\n        lora_b_base = b_ptr + lora_b_offset_elements + orig_token_idx * stride_bl + expert_id * stride_be\n        \n        # Initialize output accumulator for this output block\n        output = tl.zeros((BLOCK_SIZE_N,), dtype=tl.float32)\n        \n        # Process EM dimension in blocks\n        # For each EM block, compute intermediate values and accumulate to output\n        for em_block in range(tl.cdiv(EM, BLOCK_SIZE_M)):\n            em_offset = em_block * BLOCK_SIZE_M\n            em_range = em_offset + tl.arange(0, BLOCK_SIZE_M)\n            em_mask = em_range < EM\n            \n            # Load LoRA A values for this EM block: shape (BLOCK_SIZE_M, K)\n            # lora_a[em_range, :] has shape (BLOCK_SIZE_M, K)\n            lora_a_vals = tl.load(\n                lora_a_base + em_range[:, None] * stride_bk + hidden_range[None, :] * stride_bk,\n                mask=em_mask[:, None] & hidden_mask[None, :],\n                other=0.0\n            )\n            \n            # Compute intermediate values for this EM block: shape (BLOCK_SIZE_M,)\n            # intermediate[em] = sum_k(hidden[k] * lora_a[em, k])\n            intermediate = tl.sum(lora_a_vals * hidden[None, :], axis=1)\n            \n            # Load LoRA B values for this EM block: shape (N, BLOCK_SIZE_M)\n            # lora_b[:, em_range] has shape (N, BLOCK_SIZE_M)\n            lora_b_vals = tl.load(\n                lora_b_base + output_col_range[None, :] * stride_bn + em_range[:, None] * stride_bk,\n                mask=output_col_mask[None, :] & em_mask[:, None],\n                other=0.0\n            )\n            \n            # Accumulate: output[n] += sum_em(intermediate[em] * lora_b[n, em])\n            output += tl.sum(intermediate[:, None] * lora_b_vals, axis=0)\n        \n        # Apply routing weight and store output\n        output = output * weight\n        output_offset = orig_token_idx * stride_cm + k_idx * stride_cn + output_col_start\n        tl.store(\n            c_ptr + output_offset + tl.arange(0, BLOCK_SIZE_N) * stride_cn,\n            output,\n            mask=output_col_mask\n        )",
        "_fused_moe_lora": "@torch.inference_mode()\ndef _fused_moe_lora(\n    output: torch.Tensor,  # (num_tokens, top_k_num, N*len(lora_a_stacked),)\n    qcurr_hidden_states: torch.Tensor,  # (num_tokens, K,)\n    lora_a_stacked: list[\n        torch.Tensor\n    ],  # [(max_loras, num_experts, max_lora_rank, K,),...]\n    lora_b_stacked: list[\n        torch.Tensor\n    ],  # [(max_loras, num_experts, N, max_lora_rank,),...]\n    topk_weights: torch.Tensor,  # (num_tokens, top_k_num)\n    sorted_token_ids: torch.Tensor,  # (max_loras, _)\n    expert_ids: torch.Tensor,  # (max_loras, _ ,)\n    num_tokens_post_padded: torch.Tensor,  # (max_loras, )\n    max_lora_rank: int,\n    top_k_num: int,\n    block_size_m: int,\n    block_size_n: int,\n    block_size_k: int,\n    group_size_m: int,\n    mul_routed_weight: bool = False,\n) -> None:\n    \"\"\"\n    Fused MoE + LoRA forward pass.\n    \n    For each token, selects a LoRA module based on token-level LoRA mapping,\n    applies multiple expert-specific low-rank adapters to the token's hidden\n    state according to top-k expert indices.\n    \"\"\"\n    # Get tensor properties\n    num_tokens = qcurr_hidden_states.shape[0]\n    K = qcurr_hidden_states.shape[1]\n    N = lora_b_stacked[0].shape[2] if len(lora_b_stacked) > 0 else 0\n    EM = max_lora_rank\n    num_experts = lora_a_stacked[0].shape[1] if len(lora_a_stacked) > 0 else 0\n    max_loras = lora_a_stacked[0].shape[0] if len(lora_a_stacked) > 0 else 0\n    \n    # Get pointers to LoRA weights\n    device = qcurr_hidden_states.device\n    \n    # For now, handle single slice case\n    lora_a_ptr = lora_a_stacked[0]\n    lora_b_ptr = lora_b_stacked[0]\n    \n    # Calculate grid dimensions\n    num_token_blocks = triton.cdiv(num_tokens, block_size_m)\n    num_output_blocks = triton.cdiv(N, block_size_n)\n    grid = (num_token_blocks * num_output_blocks,)\n    \n    # Launch kernel\n    _fused_moe_lora_kernel[grid](\n        qcurr_hidden_states,  # a_ptr - hidden states\n        lora_a_ptr,  # b_ptr - LoRA A weights (B is at offset)\n        output,  # c_ptr - output\n        topk_weights,  # topk_weights_ptr\n        sorted_token_ids,  # sorted_token_ids_ptr\n        expert_ids,  # expert_ids_ptr\n        num_tokens_post_padded,  # num_tokens_post_padded_ptr\n        N,  # output dimension\n        K,  # hidden dimension\n        EM,  # max_lora_rank\n        num_tokens,  # num_valid_tokens\n        num_experts,  # num_experts\n        # Strides for hidden states (a_ptr)\n        qcurr_hidden_states.stride(0),  # stride_am - stride for token dimension\n        qcurr_hidden_states.stride(1),  # stride_ak - stride for hidden dimension\n        # Strides for LoRA weights (b_ptr)\n        lora_a_ptr.stride(0),  # stride_bl - stride for lora dimension\n        lora_a_ptr.stride(1),  # stride_be - stride for expert dimension\n        lora_a_ptr.stride(2),  # stride_bk - stride for rank dimension (EM)\n        lora_b_ptr.stride(2),  # stride_bn - stride for output dimension (N)\n        # Strides for output (c_ptr)\n        output.stride(0),  # stride_cm - stride for token dimension\n        output.stride(1),  # stride_cn - stride for expert dimension\n        # Strides for expert_ids\n        expert_ids.stride(1) if expert_ids.ndim > 1 else 1,  # stride_tl - stride for top-k dimension\n        expert_ids.stride(0) if expert_ids.ndim > 1 else 1,  # stride_el - stride for token dimension\n        # Meta-parameters\n        len(lora_a_stacked),  # num_slice_a\n        len(lora_b_stacked),  # num_slice_c\n        lora_a_ptr.shape[2] if len(lora_a_stacked) > 0 else 0,  # slice_a_size\n        lora_b_ptr.shape[2] if len(lora_b_stacked) > 0 else 0,  # slice_c_size\n        top_k_num,  # top_k\n        mul_routed_weight,  # MUL_ROUTED_WEIGHT\n        block_size_m,  # BLOCK_SIZE_M\n        block_size_n,  # BLOCK_SIZE_N\n        block_size_k,  # BLOCK_SIZE_K\n        group_size_m,  # GROUP_SIZE_M\n    )"
